// Looks up road preset ID from direction data tables.
int32_t __fastcall DRLGOUTPLACE_GetRoadPresetId(int32_t nDirX, int32_t nDirY, int32_t nRoadType) {
    int32_t nDirection = gaRoadPresetDirectionLookup[nDirX + nDirY * 3 + 4];
    if (nRoadType >= 4) {
      return gRoadPresetIdLookupTable[nRoadType - 4 + nDirection * 2];
    }

    return gnOutdoorsGridWidthByLevel[nRoadType + nDirection * 4 + 5];
}

// Extended road preset lookup with directional offsets.
int32_t __fastcall DRLGOUTPLACE_GetAdjacentRoadPresetId(int32_t nDirX, int32_t nDirY, int32_t nPrevDirX, int32_t nPrevDirY, int32_t nRoadType) {
    if (nDirX < 0) {
      nDirX += -2;
    } else if (0 < nDirX) {
      nDirX += 2;
    }
    if (nPrevDirX < 0) {
      nPrevDirX += -2;
    } else if (0 < nPrevDirX) {
      nPrevDirX += 2;
    }

    int nTableIndex = gaOutPlaceAdjacentRoadIndex[nDirX + (nPrevDirX + nPrevDirY) * 9 + nDirY + 0x28];
    if (nTableIndex == -1) {
      return 0;
    }
    if (nRoadType >= 4) {
      return gRoadPresetIdLookupTable[nRoadType - 6 + nTableIndex * 2];
    }

    return gnOutdoorsGridWidthByLevel[nRoadType + nTableIndex * 4 + 1];
}

// Iterates all four border edges of an outdoor DRLG level grid, scanning inward from each edge and marking contiguous non-solid cells with flag 0x100 (blank/border) until a solid cell is encountered. Used during outdoor level generation to suppress tile rendering at level boundaries.
void __fastcall SetBlankBorderGridCells(D2DrlgLevelStrc * pLevel) {
    int32_t nGridX;
    int32_t nScanX;
    int nY;
    int aDirTable[16];
    int32_t nBorderX;
    int nDx;
    int nDy;
    D2DrlgLevelDataWildernessLevel* pDVar1 = pLevel->pDrlgLevelData.pDrlgLevelOutdoorsData;
    aDirTable[6] = -1;
    aDirTable[0xb] = -1;
    aDirTable[0xe] = -1;
    aDirTable[0xf] = -1;
    int* pDirRow = aDirTable + 1;
    aDirTable[0] = 0;
    aDirTable[1] = 0;
    aDirTable[2] = 1;
    aDirTable[3] = 1;
    aDirTable[4] = 1;
    aDirTable[5] = 0;
    aDirTable[7] = 1;
    aDirTable[8] = 0;
    aDirTable[9] = 1;
    aDirTable[10] = 1;
    aDirTable[0xc] = 1;
    aDirTable[0xd] = 1;
    D2DrlgGridStrc* pDrlgGrid = &pDVar1->sGridOutdoor;
    for (int nDirCount = 0; nDirCount < 4; nDirCount++) {
      uint32_t nGridFlags;
      nGridX = 0;
      if (pDirRow[-1]) {
        nGridX = pDVar1->nGridCoordsWidth - 1;
      }

      nY = 0;
      if (*pDirRow) {
        nY = pDVar1->nGridCoordsHeight - 1;
      }

      nDx = pDirRow[1];
      nDy = pDirRow[2];
      nGridFlags = DrlgGrid::GetGridFlags(pDrlgGrid, nGridX, nY);
      while (!(nGridFlags & 1)) {
        nGridFlags = DrlgGrid::GetGridFlags(pDrlgGrid, nGridX, nY);
        nScanX = nGridX;
        while (!(nGridFlags & 1)) {
          DrlgGrid::AlterGridFlag(pDrlgGrid, nScanX, nY, 0x100, 0);
          nScanX += nDx;
          nGridFlags = DrlgGrid::GetGridFlags(pDrlgGrid, nScanX, nY);
        }

        nY += nDy;
        nGridFlags = DrlgGrid::GetGridFlags(pDrlgGrid, nGridX, nY);
      }

      pDirRow += 4;
    }
}

void __fastcall SetOutGridLinkFlags(D2DrlgLevelStrc * pLevel) {
    int32_t nLinkVisFlag;
    D2DrlgLevelDataWildernessLevel* pLevelData = pLevel->pDrlgLevelData.pDrlgLevelOutdoorsData;
    D2DrlgVertexStrc* pDrlgVertex = pLevelData->pVertices;
    D2DrlgVertexStrc* pNextVertex = pDrlgVertex->pNext;
    do {
      if (pDrlgVertex->dwFlags & 1) {
        nLinkVisFlag = Outdoors::GetOutLinkVisFlag(pLevel, pDrlgVertex);
        const uint32_t nGridFlags = pDrlgVertex->nDirection != 0 ? 0x3U : 0x1U;
        DrlgGrid::DRLGGRID_SetEdgeGridFlags(&pLevelData->sGridLink, pDrlgVertex, nLinkVisFlag, 0, 1);
        DrlgGrid::DRLGGRID_SetEdgeGridFlags(&pLevelData->sGridOutdoor, pDrlgVertex, nGridFlags, 0, 1);
      }

      pDrlgVertex = pNextVertex;
      pNextVertex = pNextVertex->pNext;
    } while (pDrlgVertex != pLevelData->pVertices);
}

