// Selects and spawns border tiles and random preset rooms for the three Kurast outdoor levels (Docktown 0x4F, Upper Kurast 0x50, Causeway 0x51) and the spider-cavern placeholder (0x52). Dispatches to level-specific border builders then places fixed and randomly-seeded DS1 preset files.
void __fastcall BuildKurast(D2DrlgLevelStrc * pLevel) {
    int nLevelWidthCells = pLevel->eD2LevelId;
    switch (nLevelWidthCells) {
      case 0x4f:
        {
          DRLGOUTJUNG_BuildKurastDocktownBorders(pLevel);
          break;
        }
      case 0x50:
        {
          DRLGOUTJUNG_BuildKurastUpperBorders(pLevel);
          break;
        }
      case 0x51:
        {
          DRLGOUTJUNG_BuildKurastCausewayBorders(pLevel);
          break;
        }
    }

    nLevelWidthCells = pLevel->sCoordinatesAndSize.WorldSize.x;
    int nLevelHeightCells = pLevel->sCoordinatesAndSize.WorldSize.y;
    nLevelWidthCells = nLevelWidthCells / 8 - 4;
    nLevelHeightCells = nLevelHeightCells / 8 - 4;
    switch (pLevel->eD2LevelId) {
      case 0x4f:
        Outdoors::SpawnOutdoorLevelPreset(pLevel, 0x277, 0, 0, '\x0f');
      OutJung::SpawnRandomPreset(pLevel, 0x26a, 0x26a, 4);
      OutJung::SpawnRandomPreset(pLevel, 0x268, 0x269, 0);
      OutJung::SpawnRandomPreset(pLevel, 0x267, 0x267, 0);
      return;
      case 0x50:
        Outdoors::SpawnOutdoorLevelPresetEx(pLevel, 3, 3, 0x275, 0, 0);
      Outdoors::SpawnOutdoorLevelPresetEx(pLevel, nLevelWidthCells, 3, 0x275, 1, 0);
      Outdoors::SpawnOutdoorLevelPreset(pLevel, 0x276, 0, 0, '\x0f');
      Outdoors::SpawnOutdoorLevelPreset(pLevel, 0x276, 1, 0, '\x0f');
      Outdoors::SpawnOutdoorLevelPreset(pLevel, 0x277, 0, 0, '\x0f');
      OutJung::SpawnRandomPreset(pLevel, 0x27b, 0x27b, 4);
      OutJung::SpawnRandomPreset(pLevel, 0x279, 0x27a, 0);
      OutJung::SpawnRandomPreset(pLevel, 0x278, 0x278, 0);
      return;
      case 0x51:
        Outdoors::SpawnOutdoorLevelPresetEx(pLevel, 3, nLevelHeightCells, 0x286, 0, 0);
      Outdoors::SpawnOutdoorLevelPresetEx(pLevel, nLevelWidthCells, nLevelHeightCells, 0x286, 1, 0);
      Outdoors::SpawnOutdoorLevelPreset(pLevel, 0x287, 0, 0, '\x0f');
      Outdoors::SpawnOutdoorLevelPreset(pLevel, 0x287, 1, 0, '\x0f');
      Outdoors::SpawnOutdoorLevelPreset(pLevel, 0x277, 0, 0, '\x0f');
      OutJung::SpawnRandomPreset(pLevel, 0x28b, 0x28b, 4);
      OutJung::SpawnRandomPreset(pLevel, 0x289, 0x28a, 0);
      OutJung::SpawnRandomPreset(pLevel, 0x288, 0x288, 0);
      return;
      case 0x52:
        Outdoors::SpawnOutdoorLevelPresetEx(pLevel, 0, 0, 0x28c, 0, 0);
    }
}

void __fastcall BuildTravincal(D2DrlgLevelStrc * pLevel) {
    if (pLevel->eD2LevelId != 0x53) {
      return;
    }

    Outdoors::SpawnOutdoorLevelPresetEx(pLevel, 0, 0, 0x28d, -1, 0);
    Outdoors::SpawnOutdoorLevelPresetEx(pLevel, 2, 0, 0x28e, -1, 0);
    Outdoors::SpawnOutdoorLevelPresetEx(pLevel, 6, 0, 0x28f, -1, 0);
    Outdoors::SpawnOutdoorLevelPresetEx(pLevel, 0, 4, 0x290, -1, 0);
    Outdoors::SpawnOutdoorLevelPresetEx(pLevel, 2, 4, 0x291, -1, 0);
    Outdoors::SpawnOutdoorLevelPresetEx(pLevel, 6, 4, 0x292, -1, 0);
}

void __fastcall InitAct3OutdoorLevel(D2DrlgLevelStrc * pLevel) {
    SetOutGridLinkFlags(pLevel);
    OutJung::BuildJungle(pLevel);
    BuildKurast(pLevel);
    BuildTravincal(pLevel);
}

